from slugify import slugify


def test_basic_slug():
    assert slugify("Hello World") == "hello-world"


def test_special_characters_collapsed():
    assert slugify("  foo---bar!!baz  ") == "foo-bar-baz"


def test_uppercase_lowercased():
    assert slugify("Héllo WORLD") == "h-llo-world"


def test_leading_trailing_hyphens_stripped():
    assert slugify("---test---") == "test"


def test_digits_preserved():
    assert slugify("Python 3.12 release") == "python-3-12-release"

